extends Resource
class_name ItemData

@export var id: String
@export var quantity: int
@export var rarity: int

extends Resource
class_name GameSaveData

@export var player_position: Vector2
@export var inventory: Array[ItemData]
@export var unlocked_levels: PackedStringArray
@export var last_played: int

extends RefCounted
class_name SaveManager

static func _resolve_path(path: String, binary: bool) -> String:
	var ext = ".res" if binary else ".tres"
	if path.ends_with(".res") or path.ends_with(".tres"):
		return path
	return path + ext

static func save_to_disk(data: GameSaveData, path: String, binary: bool) -> int:
	var final_path = _resolve_path(path, binary)
	return ResourceSaver.save(data, final_path)

static func load_from_disk(path: String) -> GameSaveData:
	var tres = path.ends_with(".tres")
	var res = path.ends_with(".res")
	var base = path
	if tres or res:
		base = path.substr(0, path.length() - 5)

	if tres:
		return ResourceLoader.load(base + ".tres") as GameSaveData
	elif res:
		return ResourceLoader.load(base + ".res") as GameSaveData

	if FileAccess.file_exists(base + ".tres"):
		return ResourceLoader.load(base + ".tres") as GameSaveData
	elif FileAccess.file_exists(base + ".res"):
		return ResourceLoader.load(base + ".res") as GameSaveData
	return null

static func compute_hash(data: GameSaveData) -> String:
	var ctx := HashingContext.new()
	ctx.start(HashingContext.HASH_SHA256)

	ctx.update(str(data.player_position).to_utf8_buffer())

	for item in data.inventory:
		ctx.update(item.id.to_utf8_buffer())
		ctx.update(str(item.quantity).to_utf8_buffer())
		ctx.update(str(item.rarity).to_utf8_buffer())

	for level in data.unlocked_levels:
		ctx.update(level.to_utf8_buffer())

	ctx.update(str(data.last_played).to_utf8_buffer())

	return ctx.finish().hex_encode().to_lower()
